/**
 * Reusable greeting API.
 *
 * `greet()` returns `Hello, world!`; `greet('Ada')` returns `Hello, Ada!`.
 * A blank or whitespace-only name is rejected with a TypeError.
 */
export function greet(name: string = 'world'): string {
  if (typeof name !== 'string' || name.trim().length === 0) {
    throw new TypeError('name must be a non-blank string')
  }
  return `Hello, ${name}!`
}

