#!/usr/bin/env node
/**
 * Thin executable adapter over the greeting API. See docs/ux-canon.md for the
 * terminal contract: greeting on stdout, usage on stderr for failures,
 * `--help` exits 0, unknown options exit 1.
 */
import { greet } from './index.js'

export const USAGE = 'Usage: greenfield-proof [name]\n       greenfield-proof --help'

const args = process.argv.slice(2)

if (args.length === 1 && args[0] === '--help') {
  console.log(USAGE)
} else if (args.length > 1 || args.some((arg) => arg.startsWith('-'))) {
  console.error(USAGE)
  process.exitCode = 1
} else {
  try {
    console.log(greet(args[0]))
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error))
    console.error(USAGE)
    process.exitCode = 1
  }
}

