import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import test from 'node:test'
import { fileURLToPath } from 'node:url'

const cli = fileURLToPath(new URL('../dist/cli.js', import.meta.url))
const run = (...args) => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' })
const USAGE = 'Usage: greenfield-proof [name]\n       greenfield-proof --help\n'

test('CLI prints the default greeting', () => {
  const result = run()
  assert.equal(result.status, 0)
  assert.equal(result.stdout, 'Hello, world!\n')
  assert.equal(result.stderr, '')
})

test('CLI prints the greeting for a name', () => {
  const result = run('Ada')
  assert.equal(result.status, 0)
  assert.equal(result.stdout, 'Hello, Ada!\n')
  assert.equal(result.stderr, '')
})

test('--help exits 0 with stable usage on stdout', () => {
  const result = run('--help')
  assert.equal(result.status, 0)
  assert.equal(result.stdout, USAGE)
  assert.equal(result.stderr, '')
})

test('unknown options exit 1 with usage on stderr', () => {
  for (const args of [['--unknown'], ['-x'], ['--help', '--unknown']]) {
    const result = run(...args)
    assert.equal(result.status, 1)
    assert.equal(result.stdout, '')
    assert.equal(result.stderr, USAGE)
  }
})

test('blank names and surplus arguments exit 1 with usage', () => {
  for (const args of [[''], ['   '], ['Ada', 'Grace']]) {
    const result = run(...args)
    assert.equal(result.status, 1)
    assert.equal(result.stdout, '')
    assert.match(result.stderr, /Usage: greenfield-proof \[name\]/)
  }
})

